function stopvideos(carouselPage,pageName,assetID,imageType)
{
	var sessionContainer = $("#sessionContainer").val();
	var iframeid = '#'+sessionContainer;
	var url = $(iframeid).attr('src');
	if(typeof url != 'undefined' && url.indexOf("&autoplay=1") > -1)
	{
		url = url.replace("&autoplay=1","");
	}
	$(iframeid).attr('src', url);
	try{
	jwplayer(sessionContainer).stop();
	}catch(err){

	}
	//sessionContainer = $("#sessionContainer").val(videoContainer);
	if(pageName.indexOf("Photo Open") > -1){
		$('.icon-pinterest').show();
	}
	else{
		 $('.icon-pinterest').hide();
	}
	omniture_corousal(carouselPage,pageName,assetID,imageType);
}
function getPrevClicks(countPrev)
{
	omniture_corousal('Carousel lightbox Page','prev');
	if(countPrev > 5){
	for (var i=1; i<1; i++) {
		try{
		jwplayer("videoContainer_"+i).stop();
		}catch(err){
		}
		var iframeid = "#videoContainer_"+i;
		var url = $(iframeid).attr('src');
		if(typeof url != 'undefined' && url.indexOf("&autoplay=1") > -1)
		{

			url = url.replace("&autoplay=1","");
		}
		$(iframeid).attr('src', url);
    }
	}
}
function getNextClicks(countNext)
{
	omniture_corousal('Carousel lightbox Page','next');
	if(countNext > 5){
	for (var i=1; i<1; i++) {
		try{
		jwplayer("videoContainer_"+i).stop();
		}catch(err){
		}
		var iframeid = "#videoContainer_"+i;
		var url = $(iframeid).attr('src');
		if(typeof url != 'undefined' && url.indexOf("&autoplay=1") > -1)
		{

			url = url.replace("&autoplay=1","");
		}
		$(iframeid).attr('src', url);
    }
	}

}

